SQL_DOC.P_SQL:
SELECT A.BUYER AS BUYER, A.STATUS AS STATUS, A.QUOTATION_NO AS QUOTATION_NO, A.QUOTATION_SEQ AS QUOTATION_SEQ, A.REVISION AS REVISION, A.BUYER_ITEM_NO AS BUYER_ITEM_NO, NVL(B.AGENT,' ') AS AGENT, NVL(A.ATOB_UNIT_PRICE,0) AS UNIT_PRICE, NVL(A.ATOB_DATE,' ') AS ATOB_DATE, NVL(SUBSTRB(REPLACE(REPLACE(REPLACE(A.ATOB_REMARK, CHR(13),NULL),CHR(10),NULL),',',' '),1,100),' ') AS REMARK FROM KEPRQDT A, KEPQTDT B, ICOMCMPY C, ICOMTRXL D WHERE D.DOC_NAME = 'QTHDDOWN' AND D.TARGET IN ('KRILHW0001','KRILHW0002') AND D.TARGET = A.BUYER AND D.KEY_1 = A.QUOTATION_NO AND D.KEY_2 = A.QUOTATION_SEQ AND D.KEY_3 = A.REVISION AND A.STATUS IN ('C','R') AND A.BUYER = B.BUYER AND A.QUOTATION_NO= B.QUOTATION_NO AND A.QUOTATION_SEQ= B.QUOTATION_SEQ AND A.REVISION = B.REVISION AND B.BID_SUCCESS_FLAG = 'Y' AND B.STATUS IN ('C','R') AND B.AGENT = C.COM_CODE AND D.TARGET = '$G_RS.BUYER$' AND D.KEY_1 = '$G_RS.QUOTATION_NO$' AND D.KEY_2 = '$G_RS.QUOTATION_SEQ$' AND D.KEY_3 = '$G_RS.REVISION$' ORDER BY A.BUYER,A.QUOTATION_NO,A.QUOTATION_SEQ
BEGIN
UPDATE KEPRQDT SET SEND_DATE = TO_CHAR(SYSDATE,'YYYYMMDD'), SEND_TIME = TO_CHAR(SYSDATE,'HH24MISS') WHERE BUYER = '$G_RS.BUYER$' AND QUOTATION_NO = '$G_RS.QUOTATION_NO$' AND QUOTATION_SEQ = '$G_RS.QUOTATION_SEQ$' AND REVISION = '$G_RS.REVISION$' ;
UPDATE ICOMTRXL SET KEY_10 = 'D', KEY_9 = TO_CHAR(SYSDATE,'YYYYMMDD HH24MISS') WHERE DOC_NAME = '$G_RS.DOC_NAME$' AND TARGET = '$G_RS.BUYER$' AND KEY_1 = '$G_RS.QUOTATION_NO$' AND KEY_2 = '$G_RS.QUOTATION_SEQ$' AND KEY_3 = '$G_RS.REVISION$' AND KEY_10 IN (' ','N') ;
END;
UPDATE ICOMTRXL SET KEY_10 = 'E', KEY_9 = TO_CHAR(SYSDATE,'YYYYMMDD HH24MISS') WHERE DOC_NAME = '$G_RS.DOC_NAME$' AND TARGET = '$G_RS.BUYER$' AND KEY_1 = '$G_RS.QUOTATION_NO$' AND KEY_2 = '$G_RS.QUOTATION_SEQ$' AND KEY_3 = '$G_RS.REVISION$' AND KEY_10 IN (' ','N')
